// Token is the bearer credential: 48 lowercase hex chars, generated by SB-04.
const t = String(($json.query || {}).t || '').trim();
if (!/^[0-9a-f]{48}$/.test(t)) return [{ json: { valid: false, http: 400, error: 'invalid_token_format' } }];
const soql = "SELECT Id, FirstName, LastName, Company, Email, MobilePhone, State, Industry, csbs__Time_in_Business__c, csbs__Estimated_Monthly_Revenue__c, csbs__Amount_Requested__c, csbs__Use_of_Proceeds__c, Emma_ESign_Token_Expiry__c FROM Lead WHERE Emma_ESign_Token__c = '" + t + "' AND IsConverted = false LIMIT 1";
return [{ json: { valid: true, token: t, prefill_soql: soql } }];

// ONLY chat-collected application fields leave this endpoint — never internal ids beyond the record ref, never owner/underwriting data.

// Distinguish "lookup failed" from "no such token". An error item on the Salesforce branch
// carries .error and no .records; treating that as 404 tells the funnel the link is fake and
// renders a blank form, so a merchant with a valid token retypes everything. 5xx instead —
// the funnel's proxy maps any non-2xx that is not 400/404/410 to prefill_unavailable.
let sf = null;
try { sf = $('Salesforce: Lead By Token').first().json; } catch (e) { sf = null; }
const lookupFailed = !sf || sf.error !== undefined || sf.records === undefined;
if (lookupFailed) {
  console.log(JSON.stringify({ level: 'error', workflow: 'SB-12', action: 'prefill_lookup_failed', detail: String((sf && sf.error && (sf.error.message || sf.error)) || 'no records field').slice(0, 200), ts: new Date().toISOString() }));
  return [{ json: { http: 503, body: { error: 'prefill_unavailable' } } }];
}

const rec = (sf.records || [])[0] || null;
if (!rec) return [{ json: { http: 404, body: { error: 'token_not_found' } } }];
const exp = rec.Emma_ESign_Token_Expiry__c;
if (exp && new Date(exp).getTime() < Date.now()) return [{ json: { http: 410, body: { error: 'token_expired' } } }];

// Placeholders must never prefill a form. Salesforce requires LastName, so intake writes
// 'Unknown'; Industry picks up an org-level default. Prefilling those means the merchant has
// to notice and delete junk — strictly worse than an empty field.
const PLACEHOLDERS = new Set(
  [$env.SF_COMPANY_PLACEHOLDER || 'Unknown (Sendblue AI intake)']
    .concat(String($env.SF_PLACEHOLDER_VALUES || 'Unknown,Other - Other,Other,N/A,None,TBD').split(','))
    .map(s => String(s).trim().toLowerCase())
    .filter(Boolean)
);
const clean = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (!s || PLACEHOLDERS.has(s.toLowerCase())) return null;
  return v;
};

console.log(JSON.stringify({ level: 'info', workflow: 'SB-12', action: 'prefill_served', lead: rec.Id, ts: new Date().toISOString() }));
return [{ json: { http: 200, body: {
  first_name: clean(rec.FirstName),
  last_name: clean(rec.LastName),
  business_name: clean(rec.Company),
  email: clean(rec.Email),
  phone: clean(rec.MobilePhone),
  business_state: clean(rec.State),
  industry: clean(rec.Industry),
  time_in_business: clean(rec.csbs__Time_in_Business__c),
  monthly_gross_revenue: rec.csbs__Estimated_Monthly_Revenue__c ?? null,
  requested_amount: rec.csbs__Amount_Requested__c ?? null,
  use_of_funds: clean(rec.csbs__Use_of_Proceeds__c)
} } }];
